<?php require dirname(__DIR__).'/lib.php';admin_required();$status=(string)($_GET['status']??'all');$q=trim((string)($_GET['q']??''));$where=[];$args=[];if(in_array($status,['received','shipped'],true)){$where[]='status=?';$args[]=$status;}if($q!==''){$where[]='(recipient_name LIKE ? OR phone LIKE ? OR order_no LIKE ? OR road_address LIKE ? OR referrer LIKE ?)';for($i=0;$i<5;$i++)$args[]='%'.$q.'%';}$st=db()->prepare('SELECT * FROM apple_orders'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY created_at DESC');$st->execute($args);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="apple_orders_'.date('Ymd_His').'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['주문번호','접수일시','수령자','연락처','우편번호','도로명주소','상세주소','상품','수량','추천인','배송요청','상태','배송처리일시']);while($r=$st->fetch()){ $cells=[$r['order_no'],$r['created_at'],$r['recipient_name'],$r['phone'],$r['postcode'],$r['road_address'],$r['detail_address'],$r['product_name'],$r['quantity'],$r['referrer'],$r['delivery_request'],$r['status']==='shipped'?'배송처리':'배송대기',$r['shipped_at']];fputcsv($out,array_map(static function($v){$s=(string)($v??'');return preg_match('/^[\s]*[=+@\-]/u',$s)?"'".$s:$s;},$cells));}fclose($out);
